    "helmetIcon", "helmetRack", "legionCard", "legionDashboard",
    "legionRoster", "legionStats", "pagerControl", "patrolBoard",
    "patrolLog", "patrolLogEntry", "rationBoard", "rationRow",
    "rationSummary", "rationTable", "reportPanel", "sectionTitle",
    "shieldBadge", "shieldList", "shieldWall", "standardBearer",
    "standardBearerList", "supplyCrate", "supplyGauge", "supplyOverview",
    "tentInspector", "tentMap", "tentRow", "watchSchedule"
]

# Registered AngularJS directives (not built-in ng-* directives)
directives = [
    "autoFocus", "confirmClick", "stickyHeader", "tooltipHint", "uiView"
]

# Also check for ng- directives
ng_directives = [
    "ngIf", "ngInclude", "ngRepeat", "ngClass", "ngBind", "ngClick",
    "ngDisabled", "ngShow", "ngHide", "ngFor", "ngSwitch"
]

def to_kebab(camel):
    s1 = re.sub('(.)([A-Z][a-z]+)', r'\1-\2', camel)
    return re.sub('([a-z0-9])([A-Z])', r'\1-\2', s1).lower()

leaf_components = []
dead_components = []
used_components = set()

# Analyze each component
for comp in components:
    kebab = to_kebab(comp)

    # Find the component file
    comp_file = None
    template_content = None

    # Search for component definition
    for root, dirs, files in os.walk(ajs_path):
        for file in files:
            if file.endswith(('.js', '.ts')):
                filepath = os.path.join(root, file)
                try:
                    with open(filepath, 'r', encoding='utf-8') as f:
                        content = f.read()
                        if f'.component("{comp}"' in content:
                            comp_file = filepath
                            # Extract template
                            template_match = re.search(r'template\s*:\s*[`"\']([^`"\']+)[`"\']', content, re.DOTALL)
                            if template_match:
                                template_content = template_match.group(1)
                            else:
                                template_match = re.search(r'templateUrl\s*:\s*["\']([^"\']+)["\']', content)
                                if template_match:
                                    template_url = template_match.group(1)
                                    template_path = os.path.join(workspace, template_url)
                                    if os.path.exists(template_path):
                                        with open(template_path, 'r', encoding='utf-8') as tf:
                                            template_content = tf.read()
                            break
                except:
                    pass
        if comp_file:
            break

    # Check if component is used anywhere
    is_used = False
    for root, dirs, files in os.walk(workspace):
        for file in files:
            if file.endswith(('.html', '.js', '.ts')):
                # Skip the component definition file itself
                filepath = os.path.join(root, file)
                try:
                    with open(filepath, 'r', encoding='utf-8') as f:
                        content = f.read()
                        if f'<{kebab}' in content or f'component: "{comp}"' in content:
                            is_used = True
                            used_components.add(comp)
                            break
                except:
                    pass
        if is_used:
            break

    if not is_used:
        dead_components.append(comp)
    elif template_content:
        # Check if template is a leaf component
        is_leaf = True

        # Check for other components
        for other_comp in components:
            if other_comp != comp:
                other_kebab = to_kebab(other_comp)
                if f'<{other_kebab}' in template_content:
                    is_leaf = False
                    break

        # Check for directives
        if is_leaf:
            for directive in directives:
                directive_kebab = to_kebab(directive)
                if directive_kebab in template_content.lower():
                    is_leaf = False
                    break

        # Check for ng-* directives
        if is_leaf:
            if re.search(r'ng-\w+|ng\w+', template_content):
                is_leaf = False

        if is_leaf:
            leaf_components.append(comp)

print("DEAD:", dead_components)
print("LEAF:", leaf_components)
